pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        uint256 premium,
        uint256 strike,
        bytes32 r,
        bytes32 s
    ) public {
        duration = bound(duration, 0, 9999 days);
        vm.assume(expiration > block.timestamp);

        FakeERC20 baseAsset = new FakeERC20();
        ERC1271Signer maker = new ERC1271Signer();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: false,
            baseAsset: address(baseAsset),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory signature = abi.encodePacked(r, s, uint8(27));

        c.fillOrder(order, signature, floorAssetTokenIds);

        bytes32 orderHash = c.hashOrder(order);
        assertTrue(c.positionExpirations(uint256(orderHash)) == 0);
    }
}

